import{_ as a,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Destaques de trecho","description":"","frontmatter":{"title":"Destaques de trecho","id":"eproc-destaques-trecho","plataforma":"eproc","grupo":"Destaques e lembretes","plano":"free","desde":"1.1.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-destaques-trecho.md","filePath":"funcionalidades/eproc-destaques-trecho.md"}'),t={name:"funcionalidades/eproc-destaques-trecho.md"};function d(c,e,i,u,l,n){return o(),r("div",null,e[0]||(e[0]=[s('<h1 id="destaques-de-trecho" tabindex="-1">Destaques de trecho <a class="header-anchor" href="#destaques-de-trecho" aria-label="Permalink to &quot;Destaques de trecho&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Permite marcar com cor um trecho da descrição de um evento, como um marca-texto. O destaque fica salvo e reaparece sempre que você abrir o processo. Também é possível destacar um termo em todos os processos.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, descrição dos eventos. O gerenciamento fica nas configurações do eploc, no card do recurso (&quot;Gerenciar destaques e combinações de cores&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Selecione com o mouse um trecho da descrição de um evento.</li><li>Na pequena barra que aparece ao lado da seleção, clique no botão de marca-texto (&quot;Adicionar destaque&quot;).</li><li>Escolha a cor do texto, a cor de fundo ou as duas. Combinações já usadas aparecem como atalhos (&quot;Usar esta combinação&quot;).</li><li>Para editar ou excluir um destaque, passe o mouse sobre ele e use &quot;Editar destaque&quot; ou &quot;Excluir destaque&quot;.</li><li>Para que um destaque valha em todos os processos, abra o gerenciador de destaques nas configurações do eploc e marque-o como global.</li></ol><p>Sem selecionar nada, ao passar o mouse sobre a descrição de um evento a mesma barra aparece para destacar a descrição inteira (uma borda pontilhada mostra o que será destacado). A barra também traz o botão de lembrete rápido (veja <a href="./eproc-lembrete-prefill">Criar Novo Lembrete rápido</a>).</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Oferecer o botão de destaque ao passar o mouse sobre texto sem seleção</td><td>ligada</td><td>Desligada, o botão só aparece quando você seleciona um trecho. Também pode ser desligada pelo próprio botão.</td></tr></tbody></table><p>No card, <strong>Gerenciar destaques e combinações de cores</strong> abre a lista de destaques salvos, com opção de excluir, tornar global e apagar combinações de cores.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O destaque precisa estar num trecho contínuo de uma única descrição de evento.</li><li>Os destaques ficam neste computador e entram no backup (arquivo ou Google Drive).</li><li>Excluir um destaque não pode ser desfeito.</li></ul>',13)]))}const q=a(t,[["render",d]]);export{m as __pageData,q as default};
